from collections import defaultdict

# Get all Scandinavian tasks
scandinavian_keywords = ['Norwegian', 'Swedish', 'Danish']
results_dir = Path('/root/.cache/mteb/results/results')

# First, let's find all unique Scandinavian tasks
scandinavian_tasks = set()

for model_dir in results_dir.iterdir():
    if not model_dir.is_dir():
        continue

    for revision_dir in model_dir.iterdir():
        if not revision_dir.is_dir():
            continue

        for task_file in revision_dir.glob('*.json'):
            task_name = task_file.stem

            # Check if it's a Scandinavian task
            is_scandinavian = any(keyword in task_name for keyword in scandinavian_keywords)
            if is_scandinavian:
                scandinavian_tasks.add(task_name)

print(f"Found {len(scandinavian_tasks)} unique Scandinavian tasks:")
for task in sorted(scandinavian_tasks):
    print(f"  {task}")

# Now find models with results for all or most of these tasks
model_scandinavian_scores = defaultdict(list)
model_task_count = defaultdict(set)

for model_dir in results_dir.iterdir():
    if not model_dir.is_dir():
        continue

    model_name = model_dir.name

    for revision_dir in model_dir.iterdir():
        if not revision_dir.is_dir():
            continue

        for task_file in revision_dir.glob('*.json'):
            task_name = task_file.stem

            if task_name not in scandinavian_tasks:
                continue

            try:
                with open(task_file) as f:
                    task_result = json.load(f)

                score = None
                if 'scores' in task_result and isinstance(task_result['scores'], dict):
                    for split_name, split_data in task_result['scores'].items():
                        if isinstance(split_data, list) and split_data:
                            first_entry = split_data[0]
                            if isinstance(first_entry, dict) and 'main_score' in first_entry:
                                score = first_entry['main_score']
                                break

                if score is not None and isinstance(score, (int, float)):
                    model_scandinavian_scores[model_name].append(score)
                    model_task_count[model_name].add(task_name)
            except:
                pass

# Filter models with at least 5 Scandinavian tasks
filtered_models = {m: (sum(model_scandinavian_scores[m])/len(model_scandinavian_scores[m]), len(model_scandinavian_scores[m])) 
                   for m in model_scandinavian_scores if len(model_scandinavian_scores[m]) >= 5}

sorted_models = sorted(filtered_models.items(), key=lambda x: x[1][0], reverse=True)

print(f"\n\nModels with at least 5 Scandinavian task results (sorted by Mean):")
print("=" * 80)
for i, (model_name, (mean, num_tasks)) in enumerate(sorted_models[:20], 1):
    print(f"{i:2d}. {model_name:50s} {mean:.4f} ({num_tasks} tasks)")

if sorted_models:
    print(f"\nBest model (with comprehensive coverage): {sorted_models[0][0]}")
